=== hook_banner/template.js
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var raw = String(v.text || "").toUpperCase();
  var badge = String(v.badge || "").trim();

  // Fit on the plain text, render keeping *highlight* markers per word.
  var K = 0.5;
  var boxW = d.vertical ? Math.round(W * 0.9) : Math.round(W * 0.72);
  var pad = d.vertical ? 22 : 20;
  var fit = MC.fit(MC.plain(raw), d.vertical
    ? { maxWidth: boxW - pad * 2, maxSize: 62, minSize: 20, k: K, maxLines: 3, lineHeight: 1.12, maxHeight: H * 0.22 }
    : { maxWidth: boxW - pad * 2, maxSize: 50, minSize: 18, k: K, maxLines: 2, lineHeight: 1.12, maxHeight: H * 0.24 });
  // map fitted lines back onto the raw words (same word count/order)
  var rawWords = raw.trim().split(/\s+/), idx = 0;
  var lines = fit.lines.map(function (l) {
    var n = l.split(" ").length, seg = rawWords.slice(idx, idx + n).join(" ");
    idx += n; return seg;
  });
  var tEl = document.getElementById("hb-text");
  tEl.style.setProperty("--hi-fg", MC.onColor(String(v.accent || "#FF4B4B"), "#121315", "#F4F1E8"));
  tEl.style.fontSize = fit.size + "px";
  var parts = MC.renderLines(tEl, lines);
  var textH = lines.length * fit.size * 1.08;
  var boxH = Math.round(textH + pad * 2 + fit.size * 0.22);

  var box = document.getElementById("hb-box");
  box.style.width = boxW + "px"; box.style.height = boxH + "px";
  box.style.left = ((W - boxW) / 2) + "px";
  box.style.top = (d.vertical ? Math.round(H * 0.085) : Math.round(H * 0.06)) + "px";
  tEl.style.top = (pad + fit.size * 0.06) + "px";

  var bEl = document.getElementById("hb-badge");
  var BS = d.vertical ? 46 : 40;
  bEl.style.width = BS + "px"; bEl.style.height = BS + "px";
  bEl.style.left = (-BS * 0.4) + "px"; bEl.style.top = (-BS * 0.45) + "px";
  var gl = document.getElementById("hb-glyph");
  gl.textContent = badge; gl.style.fontSize = Math.round(BS * 0.78) + "px";
  if (!badge) bEl.style.display = "none";

  var hi = parts.words.filter(function (w) { return w.classList.contains("mc-hi"); });

  var tl = gsap.timeline({ paused: true });
  tl.fromTo(box, { y: -boxH - 60, scale: 0.6, rotation: -4 }, { y: 0, scale: 1, rotation: 0, duration: 0.34, ease: "back.out(2)" }, 0);
  tl.fromTo(parts.words, { scale: 0, y: 14 }, {
    scale: 1, y: 0, duration: 0.22, ease: "back.out(1.8)",
    stagger: Math.min(0.06, 0.55 / Math.max(parts.words.length, 1))
  }, 0.14);
  var wordsEnd = 0.14 + Math.min(0.06, 0.55 / Math.max(parts.words.length, 1)) * parts.words.length + 0.2;
  if (hi.length) {
    tl.fromTo(hi, { scale: 1, rotation: 0 }, {
      keyframes: [{ scale: 1.14, rotation: -4 }, { scale: 0.97, rotation: 2 }, { scale: 1, rotation: -2 }],
      duration: 0.34, ease: "power1.inOut", immediateRender: false
    }, wordsEnd);
  }
  if (badge) {
    tl.fromTo(bEl, { scale: 0, rotation: -180 }, { scale: 1, rotation: -10, duration: 0.32, ease: "back.out(2.6)" }, 0.24);
    // idle wobble for the rest of the hold (finite repeat count derived from the duration)
    var start = Math.max(wordsEnd + 0.4, 1.0), cyc = 0.9;
    var reps = Math.max(0, Math.floor((d.duration - start) / cyc) - 1);
    if (d.duration - start > cyc) {
      tl.fromTo(bEl, { rotation: -10 }, { rotation: 8, duration: cyc / 2, ease: "sine.inOut", yoyo: true, repeat: reps * 2 + 1, immediateRender: false }, start);
    }
  }
  return tl;
});
