  svg.setAttribute("viewBox", "0 0 " + W + " " + H);
  var rx = tw / 2 + fit.size * 0.42, ry = th / 2 + fit.size * 0.42;
  function splat(scale, seed) {
    var r = MC.rng(seed), N = 16, pts = [];
    for (var i = 0; i < N; i++) {
      var a = (i / N) * Math.PI * 2 + (r() - 0.5) * 0.18;
      var base = 0.86 + r() * 0.14, tip = 1.18 + r() * 0.38;
