    }
    var last = pts[pts.length - 1], first = pts[0];
    s += " Q" + P([(last[0] + first[0] + Math.PI * 2) / 2, 1.0]) + " " + P(first) + " Z";
    return s;
  }
  var g = document.getElementById("ws-splat-g"), html = "";
  html += '<path d="' + splat(1.06, 7) + '" fill="#000" transform="translate(7,8)"/>';
  html += '<path d="' + splat(1.06, 7) + '" fill="' + color + '" stroke="#000" stroke-width="4" stroke-linejoin="round"/>';
  html += '<path d="' + splat(0.9, 21) + '" fill="' + INK + '"/>';
