MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var text = MC.plain(String(v.text || "BONK")).toUpperCase().trim() || "BONK";
  var color = String(v.color || "#FFCC33");
  var INK = "#121315", PAPER = "#F4F1E8";
  var rnd = MC.rng(1337 + text.length * 31);

  // ---- text (Luckiest Guy, ~0.62em per glyph incl. the chunky outline)
  var K = 0.62;
  var fit = MC.fit(text, d.vertical
    ? { maxWidth: W * 0.86, maxSize: 168, minSize: 40, k: K, maxLines: 3, lineHeight: 1.02, maxHeight: H * 0.42 }
    : { maxWidth: W * 0.8, maxSize: 190, minSize: 40, k: K, maxLines: 2, lineHeight: 1.02, maxHeight: H * 0.6 });
  var tEl = document.getElementById("ws-text");
  tEl.style.setProperty("--ws-c", color);
  tEl.style.fontSize = fit.size + "px";
  MC.renderLines(tEl, fit.lines);
  var longest = Math.max.apply(null, fit.lines.map(function (l) { return l.length; }));
  var tw = Math.min(W * 0.9, longest * fit.size * 0.6), th = fit.lines.length * fit.size * 1.02;
  var cx = W / 2, cy = H / 2;
  tEl.style.top = (cy - th / 2 + fit.size * 0.04) + "px";

  // ---- ink splat: spiky blob (outer in word colour, inner in ink) + droplets
  var svg = document.getElementById("ws-splat");
  svg.setAttribute("width", W); svg.setAttribute("height", H);
  svg.setAttribute("viewBox", "0 0 " + W + " " + H);
  var rx = tw / 2 + fit.size * 0.42, ry = th / 2 + fit.size * 0.42;
  function splat(scale, seed) {
    var r = MC.rng(seed), N = 16, pts = [];
    for (var i = 0; i < N; i++) {
      var a = (i / N) * Math.PI * 2 + (r() - 0.5) * 0.18;
      var base = 0.86 + r() * 0.14, tip = 1.18 + r() * 0.38;
      var aw = 0.07 + r() * 0.05;
      pts.push([a - aw * 2.2, base], [a - aw * 0.5, tip * 0.92], [a, tip], [a + aw * 0.5, tip * 0.92], [a + aw * 2.2, base]);
    }
    var P = function (p) { return (cx + Math.cos(p[0]) * rx * p[1] * scale).toFixed(1) + "," + (cy + Math.sin(p[0]) * ry * p[1] * scale).toFixed(1); };
    var s = "M" + P(pts[0]);
    for (var j = 1; j < pts.length; j++) {
      if (j % 5 === 0) { // bulge between spikes
        var prev = pts[j - 1];
        s += " Q" + P([(prev[0] + pts[j][0]) / 2, 1.0]) + " " + P(pts[j]);
      } else s += " L" + P(pts[j]);
    }
    var last = pts[pts.length - 1], first = pts[0];
    s += " Q" + P([(last[0] + first[0] + Math.PI * 2) / 2, 1.0]) + " " + P(first) + " Z";
    return s;
  }
  var g = document.getElementById("ws-splat-g"), html = "";
  var outer = splat(1.06, 7);
  html += '<path d="' + outer + '" fill="#000" transform="translate(7,8)"/>';
  html += '<path d="' + outer + '" fill="' + color + '" stroke="#000" stroke-width="4" stroke-linejoin="round"/>';
  html += '<path d="' + splat(0.9, 21) + '" fill="' + INK + '"/>';
  for (var i = 0; i < 7; i++) {
    var a = rnd() * Math.PI * 2, dist = 1.5 + rnd() * 0.35, rr = fit.size * (0.05 + rnd() * 0.05);
    var dx = cx + Math.cos(a) * rx * dist, dy = cy + Math.sin(a) * ry * dist;
    html += '<circle class="ws-drop" cx="' + dx.toFixed(1) + '" cy="' + dy.toFixed(1) + '" r="' + rr.toFixed(1) + '" fill="' + color + '" stroke="#000" stroke-width="3"/>';
  }
  g.innerHTML = html;
  var drops = Array.prototype.slice.call(g.querySelectorAll(".ws-drop"));

  // ---- shards: beveled blocks + triangles that fly out on impact
  var wrap = document.getElementById("ws-shards"), shards = [];
  var NS = d.vertical ? 12 : 14;
  for (var s = 0; s < NS; s++) {
    var el = document.createElement("div");
    var sz = Math.round(fit.size * (0.1 + rnd() * 0.1));
    var col = [color, PAPER, color, MC.shade(color, -0.25)][s % 4];
    if (s % 3 === 2) {
      el.className = "ws-tri";
      el.innerHTML = '<svg width="' + (sz * 1.4) + '" height="' + (sz * 1.4) + '" viewBox="0 0 10 10" style="display:block;overflow:visible"><polygon points="1,9 5,0.8 9.2,8" fill="' + col + '" stroke="#000" stroke-width="1.4" stroke-linejoin="round"/></svg>';
    } else {
      el.className = "ws-shard";
      el.style.width = sz + "px"; el.style.height = sz + "px"; el.style.background = col;
    }
    el.style.left = (cx - sz / 2) + "px"; el.style.top = (cy - sz / 2) + "px";
    wrap.appendChild(el);
    var ang = (s / NS) * Math.PI * 2 + (rnd() - 0.5) * 0.5;
    var far = 1.25 + rnd() * 0.7;
    shards.push({ el: el, x: Math.cos(ang) * rx * far, y: Math.sin(ang) * ry * far * 1.15,
      sx: Math.cos(ang) * rx * 0.45, sy: Math.sin(ang) * ry * 0.45, r: (rnd() - 0.5) * 540 });
  }

  // ---- timeline
  var IMP = 0.13;
  var stage = document.getElementById("ws-wrap");
  var tl = gsap.timeline({ paused: true });
  tl.fromTo(tEl, { scale: 4, opacity: 0, rotation: -8 }, { scale: 1, opacity: 1, rotation: -3, duration: IMP, ease: "power3.in" }, 0);
  tl.fromTo(tEl, { scaleX: 1, scaleY: 1 }, { keyframes: [{ scaleX: 1.18, scaleY: 0.78, duration: 0.05 }, { scaleX: 0.94, scaleY: 1.08, duration: 0.09 }, { scaleX: 1, scaleY: 1, duration: 0.14 }], ease: "power2.out", immediateRender: false }, IMP);
  tl.fromTo(g, { scale: 0.15, rotation: -12, opacity: 1, svgOrigin: cx + " " + cy }, { scale: 1, rotation: 0, duration: 0.24, ease: "back.out(2.2)" }, IMP - 0.02);
  tl.fromTo(drops, { scale: 0, transformOrigin: "50% 50%" }, { scale: 1, duration: 0.2, ease: "back.out(3)", stagger: 0.015 }, IMP + 0.05);
  // impact shake (decaying)
  var amp = d.vertical ? 12 : 14;
  tl.fromTo(stage, { x: 0, y: 0 }, { keyframes: [
    { x: amp, y: -amp * 0.6 }, { x: -amp * 0.8, y: amp * 0.7 }, { x: amp * 0.55, y: amp * 0.4 },
    { x: -amp * 0.35, y: -amp * 0.3 }, { x: amp * 0.15, y: amp * 0.1 }, { x: 0, y: 0 }], duration: 0.3, ease: "none", immediateRender: false }, IMP);
  tl.set(shards.map(function (o) { return o.el; }), { opacity: 0 }, 0);
  shards.forEach(function (o, i) {
    tl.fromTo(o.el, { x: o.sx, y: o.sy, opacity: 1, scale: 1.2, rotation: 0 },
      { x: o.x, y: o.y, scale: 0.5, rotation: o.r, duration: 0.6, ease: "power3.out", immediateRender: false }, IMP + i * 0.004);
    tl.to(o.el, { opacity: 0, duration: 0.2, ease: "power1.in" }, IMP + 0.42 + (i % 4) * 0.03);
  });
  // settle wobble on the word
  tl.to(tEl, { rotation: 2, duration: 0.3, ease: "sine.inOut" }, IMP + 0.3);
  tl.to(tEl, { rotation: -1, duration: 0.3, ease: "sine.inOut" }, IMP + 0.6);
  // exit
  var OUT = d.duration - 0.3;
  tl.to(tEl, { scale: 1.25, opacity: 0, duration: 0.24, ease: "power2.in" }, OUT + 0.04);
  tl.to(g, { scale: 1.12, opacity: 0, duration: 0.26, ease: "power2.in" }, OUT);
  tl.to(drops, { scale: 0, duration: 0.16, ease: "back.in(2)" }, OUT);
  return tl;
});

