MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var text = MC.plain(String(v.text || "")).toUpperCase().trim();
  var color = String(v.color || "#FF4B4B");
  var clamp = function (a, lo, hi) { return Math.max(lo, Math.min(hi, a)); };
  var tx = clamp(MC.num(v.x, 0.62), 0.04, 0.96) * W, ty = clamp(MC.num(v.y, 0.55), 0.04, 0.96) * H;
  var dirX = String(v.side || "left").toLowerCase().trim() === "right" ? 1 : -1;
  var rnd = MC.rng(4242);

  // ---- scribbled ring around the target
  var RX = d.vertical ? 66 : 64, RY = RX * 0.8;
  function smooth(pts, closed) { // Catmull-Rom -> cubic bezier
    var s = "M" + pts[0][0].toFixed(1) + "," + pts[0][1].toFixed(1);
    for (var i = 0; i < pts.length - 1; i++) {
      var p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
      s += " C" + (p1[0] + (p2[0] - p0[0]) / 6).toFixed(1) + "," + (p1[1] + (p2[1] - p0[1]) / 6).toFixed(1) + " " +
        (p2[0] - (p3[0] - p1[0]) / 6).toFixed(1) + "," + (p2[1] - (p3[1] - p1[1]) / 6).toFixed(1) + " " +
        p2[0].toFixed(1) + "," + p2[1].toFixed(1);
    }
    return s;
  }
  var ring = [], N = 26, turns = 1.16, a0 = -Math.PI * 0.62;
  for (var i = 0; i <= N; i++) {
    var t = i / N, a = a0 + t * turns * Math.PI * 2;
    var k = 1 + 0.07 * Math.sin(a * 2 + 0.6) + (rnd() - 0.5) * 0.05 + t * 0.12; // spirals out a touch
    ring.push([tx + Math.cos(a) * RX * k, ty + Math.sin(a) * RY * k + (t - 0.5) * 6]);
  }
  var ringD = smooth(ring);

  // ---- label
  var lab = document.getElementById("ca-label"), lt = document.getElementById("ca-text");
  lab.style.setProperty("--ca-c", color);
  var maxTW = d.vertical ? W * 0.62 : W * 0.3;
  var fit = MC.fit(text || " ", { maxWidth: maxTW, maxSize: d.vertical ? 40 : 36, minSize: 16, k: 0.52, maxLines: 2, lineHeight: 1.08 });
  lt.style.fontSize = fit.size + "px";
  MC.renderLines(lt, fit.lines);
  var longest = Math.max.apply(null, fit.lines.map(function (l) { return l.length; }));
  var padX = Math.round(fit.size * 0.55), padY = Math.round(fit.size * 0.38);
  var lw = Math.round(longest * fit.size * 0.52 + padX * 2), lh = Math.round(fit.lines.length * fit.size * 1.08 + padY * 2);
  lab.style.width = lw + "px"; lab.style.height = lh + "px";
  lt.style.top = (padY + fit.size * 0.08) + "px";
  var above = ty > H * (d.vertical ? 0.5 : 0.45) ? -1 : 1;
  var lcx = tx + dirX * (d.vertical ? 120 : 210), lcy = ty + above * (RY + (d.vertical ? 150 : 95));
  var M = 14, topSafe = d.vertical ? H * 0.07 : M, botSafe = d.vertical ? H * 0.8 : H - M;
  var lx = clamp(lcx - lw / 2, M, W - M - lw - 8), ly = clamp(lcy - lh / 2, topSafe, botSafe - lh - 8);
  lab.style.left = lx + "px"; lab.style.top = ly + "px";
  lcx = lx + lw / 2; lcy = ly + lh / 2;
  if (!text) lab.style.display = "none";

  // ---- arrow from the label edge to the ring edge (slight curve)
  var ux = tx - lcx, uy = ty - lcy, L = Math.hypot(ux, uy) || 1; ux /= L; uy /= L;
  var sBox = Math.min(Math.abs((lw / 2 + 8) / (ux || 1e-6)), Math.abs((lh / 2 + 8) / (uy || 1e-6)));
  var sx = lcx + ux * sBox, sy = lcy + uy * sBox;
  var eS = 1 / Math.hypot(ux / (RX * 1.2 + 10), uy / (RY * 1.2 + 10));
  var ex = tx - ux * eS, ey = ty - uy * eS;
  var len = Math.hypot(ex - sx, ey - sy);
  var hasArrow = !!text && len > 26 && L > sBox + eS;
  var bend = dirX * above * len * 0.22;
  var mx = (sx + ex) / 2 - uy * bend, my = (sy + ey) / 2 + ux * bend;
