  var longest = Math.max.apply(null, fit.lines.map(function (l) { return l.length; }));
  var padX = Math.round(fit.size * 0.55), padY = Math.round(fit.size * 0.38);
  var lw = Math.round(longest * fit.size * 0.52 + padX * 2), lh = Math.round(fit.lines.length * fit.size * 1.08 + padY * 2);
