MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var text = MC.plain(String(v.text || "")).toUpperCase().trim() || "...";
  var thought = String(v.kind || "speech").toLowerCase().trim() === "thought";
  var right = String(v.tail || "left").toLowerCase().trim() === "right";
  var clamp = function (a, lo, hi) { return Math.max(lo, Math.min(hi, a)); };
  var PAPER = "#F4F1E8", rnd = MC.rng(777);

  // ---- text + bubble size
  var fit = MC.fit(text, { maxWidth: d.vertical ? W * 0.66 : W * 0.36, maxSize: d.vertical ? 40 : 36, minSize: 16,
    k: 0.5, maxLines: 3, lineHeight: 1.1, maxHeight: d.vertical ? H * 0.2 : H * 0.3 });
  var tEl = document.getElementById("sb-text");
  tEl.style.fontSize = fit.size + "px";
  var parts = MC.renderLines(tEl, fit.lines, { chars: true });
  var longest = Math.max.apply(null, fit.lines.map(function (l) { return l.length; }));
  var textW = longest * fit.size * 0.5, textH = fit.lines.length * fit.size * 1.1;
  var padX = fit.size * (thought ? 1.25 : 0.9), padY = fit.size * (thought ? 0.95 : 0.6);
  var w = Math.round(Math.max(textW + padX * 2, fit.size * 4.2)), h = Math.round(textH + padY * 2);
  var th = clamp(h * 0.5, 30, 60);                       // tail drop below the body
  var M = 12, top = d.vertical ? H * 0.07 : M, bot = d.vertical ? H * 0.8 : H - M;
  var cx = clamp(MC.num(v.x, 0.5) * W, M + w / 2 + 8, W - M - w / 2 - 8);
  var cy = clamp(MC.num(v.y, 0.3) * H, top + h / 2, bot - h / 2 - th);
  var gx = cx - w / 2, gy = cy - h / 2;
  var g = document.getElementById("sb-group");
  g.style.left = gx + "px"; g.style.top = gy + "px"; g.style.width = w + "px"; g.style.height = h + "px";
  tEl.style.top = (padY + fit.size * 0.08) + "px";

  // ---- bubble art (local coords: body = 0..w x 0..h)
  var svg = document.getElementById("sb-svg");
  svg.setAttribute("width", w); svg.setAttribute("height", h + th);
  svg.setAttribute("viewBox", "0 0 " + w + " " + (h + th));
  var tipX, tipY = h + th, art = "";
  var f = function (n) { return n.toFixed(1); };
  if (!thought) {
    var r = Math.min(h / 2, 30);
    var b1 = w * 0.2, b2 = w * 0.38; tipX = w * 0.08;           // tail on the left (mirrored for right)
    if (right) { b1 = w - w * 0.38; b2 = w - w * 0.2; tipX = w - w * 0.08; }
    var p = "M" + r + ",0 H" + f(w - r) + " Q" + w + ",0 " + w + "," + r + " V" + f(h - r) + " Q" + w + "," + h + " " + f(w - r) + "," + h +
      " H" + f(b2) + " L" + f(tipX) + "," + f(tipY) + " L" + f(b1) + "," + h + " H" + r + " Q0," + h + " 0," + f(h - r) + " V" + r + " Q0,0 " + r + ",0 Z";
    if (right) p = "M" + r + ",0 H" + f(w - r) + " Q" + w + ",0 " + w + "," + r + " V" + f(h - r) + " Q" + w + "," + h + " " + f(w - r) + "," + h +
      " H" + f(b2) + " L" + f(tipX) + "," + f(tipY) + " L" + f(b1) + "," + h + " H" + r + " Q0," + h + " 0," + f(h - r) + " V" + r + " Q0,0 " + r + ",0 Z";
    art += '<path d="' + p + '" fill="#000" transform="translate(6,7)"/>';
    art += '<path d="' + p + '" fill="' + PAPER + '" stroke="#000" stroke-width="4.5" stroke-linejoin="round"/>';
    art += '<path d="M' + f(r * 0.7) + ',' + f(h * 0.28) + ' Q' + f(r * 0.7) + ',' + f(r * 0.6) + ' ' + f(r * 1.6) + ',' + f(r * 0.55) + '" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" opacity="0.9"/>';
  } else {
    // cloud = union of lobes: stroke pass (thick black) under a fill pass (paper)
    var ex = w / 2, ey = h / 2, lobes = [], per = Math.PI * (3 * (ex + ey) - Math.sqrt((3 * ex + ey) * (ex + 3 * ey)));
    var LR = clamp(h * 0.24, 16, 34), n = Math.max(8, Math.round(per / (LR * 1.45)));
    for (var i = 0; i < n; i++) {
      var a = (i / n) * Math.PI * 2;
      lobes.push([ex + Math.cos(a) * (ex - LR * 0.75), ey + Math.sin(a) * (ey - LR * 0.7), LR * (0.92 + rnd() * 0.22)]);
    }
    tipX = right ? w * 0.9 : w * 0.1;
    var dots = [[right ? w * 0.74 : w * 0.26, h + th * 0.18, LR * 0.42], [right ? w * 0.83 : w * 0.17, h + th * 0.58, LR * 0.28], [tipX, h + th * 0.9, LR * 0.17]];
    var shapes = function (fill, stroke, sw, dx, dy) {
      var s = '<g transform="translate(' + dx + "," + dy + ')">';
      s += '<ellipse cx="' + f(ex) + '" cy="' + f(ey) + '" rx="' + f(ex - LR * 0.6) + '" ry="' + f(ey - LR * 0.55) + '" fill="' + fill + '"' + (sw ? ' stroke="' + stroke + '" stroke-width="' + sw + '"' : "") + "/>";
      lobes.concat(dots).forEach(function (l) {
        s += '<circle cx="' + f(l[0]) + '" cy="' + f(l[1]) + '" r="' + f(l[2]) + '" fill="' + fill + '"' + (sw ? ' stroke="' + stroke + '" stroke-width="' + sw + '"' : "") + "/>";
      });
      return s + "</g>";
    };
    art += shapes("#000", "#000", 9, 6, 7) + shapes("#000", "#000", 9, 0, 0) + shapes(PAPER, "", 0, 0, 0);
  }
  svg.innerHTML = art;

  // ---- timeline
  var tl = gsap.timeline({ paused: true });
  var origin = f(tipX) + "px " + f(tipY) + "px";
  tl.fromTo(g, { scale: 0, rotation: right ? 10 : -10, transformOrigin: origin },
    { scale: 1, rotation: 0, duration: 0.34, ease: "back.out(2.2)" }, 0);
  var T0 = 0.26, per = Math.min(0.045, 1.3 / Math.max(parts.chars.length, 1));
  tl.set(parts.chars, { opacity: 0 }, 0);
  parts.chars.forEach(function (c, i) {
    tl.fromTo(c, { opacity: 0, y: -fit.size * 0.25, scale: 1.4 }, { opacity: 1, y: 0, scale: 1, duration: 0.1, ease: "back.out(3)", immediateRender: false }, T0 + i * per);
  });
  var typed = T0 + parts.chars.length * per + 0.1;
  // little "speak" bounce when typing finishes, then a gentle bob while holding (finite)
  tl.fromTo(g, { scale: 1 }, { keyframes: [{ scale: 1.06 }, { scale: 1 }], duration: 0.22, ease: "power1.inOut", immediateRender: false }, typed);
  var OUT = d.duration - 0.28, bob = 0.7, reps = Math.floor((OUT - typed - 0.25) / bob);
  if (reps >= 1) tl.fromTo(g, { y: 0 }, { y: -4, duration: bob / 2, ease: "sine.inOut", yoyo: true, repeat: reps * 2 - 1, immediateRender: false }, typed + 0.25);
  tl.to(g, { scale: 0, rotation: right ? 8 : -8, duration: 0.24, ease: "back.in(2)" }, OUT);
  return tl;
});

