    if (right) p = "M" + r + ",0 H" + f(w - r) + " Q" + w + ",0 " + w + "," + r + " V" + f(h - r) + " Q" + w + "," + h + " " + f(w - r) + "," + h +
      " H" + f(b2) + " L" + f(tipX) + "," + f(tipY) + " L" + f(b1) + "," + h + " H" + r + " Q0," + h + " 0," + f(h - r) + " V" + r + " Q0,0 " + r + ",0 Z";
    art += '<path d="' + p + '" fill="#000" transform="translate(6,7)"/>';
    art += '<path d="' + p + '" fill="' + PAPER + '" stroke="#000" stroke-width="4.5" stroke-linejoin="round"/>';
    art += '<path d="M' + f(r * 0.7) + ',' + f(h * 0.28) + ' Q' + f(r * 0.7) + ',' + f(r * 0.6) + ' ' + f(r * 1.6) + ',' + f(r * 0.55) + '" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" opacity="0.9"/>';
  } else {
