MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, V = d.vertical;
  var INK = "#121315", PAPER = "#F4F1E8";
  var names = [MC.plain(String(v.left || "")).toUpperCase().trim() || "?", MC.plain(String(v.right || "")).toUpperCase().trim() || "?"];
  var cols = [String(v.left_color || "#4FE0D6"), String(v.right_color || "#FF4B4B")];
  var label = MC.plain(String(v.label == null ? "VS" : v.label)).toUpperCase().trim();
  var f = function (n) { return n.toFixed(1); };
  var cx = W / 2, cy = H / 2, SK = V ? 34 : 46, O = 60;   // seam skew, off-canvas overdraw

  // ---- panel polygons (landscape: left/right halves of a band; vertical: top/bottom halves)
  var polys, centers, boxW, boxH;
  if (!V) {
    var BH = Math.round(H * 0.46), y0 = cy - BH / 2, y1 = cy + BH / 2;
    polys = [[[-O, y0], [cx + SK - 4, y0], [cx - SK - 4, y1], [-O, y1]], [[cx + SK + 4, y0], [W + O, y0], [W + O, y1], [cx - SK + 4, y1]]];
    centers = [[W * 0.25, cy], [W * 0.75, cy]]; boxW = W * 0.38; boxH = BH * 0.7;
  } else {
    var PH = Math.round(H * 0.2), t0 = cy - PH - SK, t1 = cy + PH + SK;
    polys = [[[-O, t0], [W + O, t0], [W + O, cy - SK - 4], [-O, cy + SK - 4]], [[-O, cy + SK + 4], [W + O, cy - SK + 4], [W + O, t1], [-O, t1]]];
    centers = [[cx, t0 + (PH) * 0.55], [cx, t1 - PH * 0.55]]; boxW = W * 0.84; boxH = PH * 0.78;
  }
  var panels = [document.getElementById("vs-pl"), document.getElementById("vs-pr")];
  var nameEls = [];
  panels.forEach(function (p, i) {
    var svg = p.querySelector(".vs-art");
    svg.setAttribute("width", W); svg.setAttribute("height", H); svg.setAttribute("viewBox", "0 0 " + W + " " + H);
    var pts = polys[i].map(function (q) { return f(q[0]) + "," + f(q[1]); }).join(" ");
    var c = cols[i], art = "";
    var clipId = "vs-clip-" + i;
    art += '<defs><clipPath id="' + clipId + '"><polygon points="' + pts + '"/></clipPath></defs>';
    art += '<polygon points="' + pts + '" fill="#000" transform="translate(7,9)"/>';
    art += '<polygon points="' + pts + '" fill="' + c + '"/>';
    // diagonal light/dark stripes + speed streaks, clipped to the panel
    art += '<g clip-path="url(#' + clipId + ')">';
    for (var s = -6; s < 14; s++) {
      var x = s * (V ? 70 : 90);
      art += '<polygon points="' + f(x) + ',-20 ' + f(x + 34) + ',-20 ' + f(x + 34 - H * 0.6) + ',' + (H + 20) + ' ' + f(x - H * 0.6) + ',' + (H + 20) + '" fill="' + MC.shade(c, 0.12) + '" opacity="0.5"/>';
    }
    var rnd = MC.rng(31 + i * 7);
    var yb = Math.min.apply(null, polys[i].map(function (q) { return q[1]; })), ye = Math.max.apply(null, polys[i].map(function (q) { return q[1]; }));
    for (var k = 0; k < 6; k++) {
      var yy = yb + (ye - yb) * (0.12 + rnd() * 0.76), xx = rnd() * W * 0.8, ll = 60 + rnd() * 140;
      art += '<rect x="' + f(xx) + '" y="' + f(yy) + '" width="' + f(ll) + '" height="4" fill="#fff" opacity="0.35"/>';
    }
    art += '<polygon points="' + pts + '" fill="none" stroke="rgba(0,0,0,0.25)" stroke-width="16"/>';
    art += "</g>";
    art += '<polygon points="' + pts + '" fill="none" stroke="#000" stroke-width="6" stroke-linejoin="round"/>';
    svg.innerHTML = art;
    // name
    var nm = p.querySelector(".vs-name");
    var fit = MC.fit(names[i], { maxWidth: boxW, maxSize: V ? 84 : 80, minSize: 22, k: 0.6, maxLines: 2, lineHeight: 1.02, maxHeight: boxH });
    nm.style.fontSize = fit.size + "px";
    MC.renderLines(nm, fit.lines);
    var th = fit.lines.length * fit.size * 1.02;
    nm.style.width = boxW + "px"; nm.style.left = (centers[i][0] - boxW / 2) + "px";
    nm.style.top = (centers[i][1] - th / 2 + fit.size * 0.06) + "px";
    var fg = MC.onColor(c, INK, PAPER);
    nm.style.color = fg;
    nm.style.setProperty("--ol", fg === INK ? PAPER : "#000");
    nameEls.push(nm);
  });

  // ---- VS badge: jagged burst + label
  var BS = V ? 150 : 150, badge = document.getElementById("vs-badge");
  badge.style.width = BS + "px"; badge.style.height = BS + "px";
  badge.style.left = (cx - BS / 2) + "px"; badge.style.top = (cy - BS / 2) + "px";
  var burst = document.getElementById("vs-burst");
  burst.setAttribute("width", BS); burst.setAttribute("height", BS); burst.setAttribute("viewBox", "0 0 " + BS + " " + BS);
  var bp = "", N = 12, rr = MC.rng(5);
  for (var i = 0; i < N * 2; i++) {
    var a = (i / (N * 2)) * Math.PI * 2 - Math.PI / 2, r = (i % 2 ? 0.36 : 0.5 - rr() * 0.04) * BS;
    bp += (i ? " L" : "M") + f(BS / 2 + Math.cos(a) * r) + "," + f(BS / 2 + Math.sin(a) * r);
  }
  var gold = MC.css("--gold") || "#FFCC33";
  burst.innerHTML = '<path d="' + bp + ' Z" fill="#000" transform="translate(5,7)"/><path d="' + bp + ' Z" fill="' + gold + '" stroke="#000" stroke-width="5" stroke-linejoin="round"/>' +
    '<circle cx="' + BS / 2 + '" cy="' + BS / 2 + '" r="' + f(BS * 0.27) + '" fill="' + INK + '" stroke="#000" stroke-width="3"/>';
  var lab = document.getElementById("vs-label");
  var ls = Math.floor(BS * (label.length > 2 ? 0.8 / label.length : 0.4));
  lab.textContent = label; lab.style.fontSize = ls + "px"; lab.style.top = (BS / 2 - ls * 0.5 + ls * 0.08) + "px";
  if (!label) badge.style.display = "none";

  // ---- sparks out of the seam on the badge hit
  var sp = document.getElementById("vs-sparks");
  sp.setAttribute("width", W); sp.setAttribute("height", H); sp.setAttribute("viewBox", "0 0 " + W + " " + H);
  var sh = "";
  for (var j = 0; j < 10; j++) {
    var aa = (j / 10) * Math.PI * 2 + 0.3, r0 = BS * 0.55, r1 = BS * (0.95 + (j % 3) * 0.18);
    sh += '<line class="vs-spark" x1="' + f(cx + Math.cos(aa) * r0) + '" y1="' + f(cy + Math.sin(aa) * r0) + '" x2="' + f(cx + Math.cos(aa) * r1) + '" y2="' + f(cy + Math.sin(aa) * r1) +
      '" stroke="' + (j % 2 ? "#fff" : gold) + '" stroke-width="7" stroke-linecap="round"/>';
  }
  sp.innerHTML = '<g id="vs-spark-g">' + sh + '</g>';
  var sparkG = document.getElementById("vs-spark-g");

  // ---- timeline
  var tl = gsap.timeline({ paused: true });
  var offL = -(V ? W + O * 2 : W * 0.62 + O), offR = V ? W + O * 2 : W * 0.62 + O;
  tl.fromTo(panels[0], { x: offL }, { x: 0, duration: 0.3, ease: "power4.out" }, 0);
  tl.fromTo(panels[1], { x: offR }, { x: 0, duration: 0.3, ease: "power4.out" }, 0.07);
  tl.fromTo(nameEls[0], { scale: 2.2, opacity: 0, rotation: -6 }, { scale: 1, opacity: 1, rotation: -3, duration: 0.24, ease: "back.out(2.4)" }, 0.2);
  tl.fromTo(nameEls[1], { scale: 2.2, opacity: 0, rotation: 6 }, { scale: 1, opacity: 1, rotation: 3, duration: 0.24, ease: "back.out(2.4)" }, 0.27);
  var HIT = 0.5;
  if (label) {
    tl.fromTo(badge, { scale: 3, rotation: -200, opacity: 0 }, { scale: 1, rotation: -8, opacity: 1, duration: 0.2, ease: "power3.in" }, HIT - 0.2);
    tl.fromTo(badge, { scale: 1 }, { keyframes: [{ scale: 1.22, duration: 0.07 }, { scale: 0.94, duration: 0.1 }, { scale: 1, duration: 0.12 }], ease: "power1.out", immediateRender: false }, HIT);
    tl.fromTo(sparkG, { scale: 0.5, opacity: 1, svgOrigin: cx + " " + cy }, { scale: 1.5, opacity: 0, duration: 0.4, ease: "power2.out" }, HIT);
  } else {
    tl.set(sparkG, { opacity: 0 }, 0);
  }
  var shake = document.getElementById("vs-shake"), A = 11;
  tl.fromTo(shake, { x: 0, y: 0 }, { keyframes: [{ x: A, y: -A * 0.5 }, { x: -A * 0.8, y: A * 0.6 }, { x: A * 0.5, y: A * 0.3 }, { x: -A * 0.25, y: -A * 0.2 }, { x: 0, y: 0 }], duration: 0.26, ease: "none", immediateRender: false }, HIT);
  // hold: panels lean toward each other, badge throbs (finite)
  var OUT = d.duration - 0.36;
  tl.to(panels[0], { x: V ? 8 : 10, duration: OUT - HIT - 0.1, ease: "sine.inOut" }, HIT + 0.1);
  tl.to(panels[1], { x: V ? -8 : -10, duration: OUT - HIT - 0.1, ease: "sine.inOut" }, HIT + 0.1);
  var cyc = 0.5, reps = Math.floor((OUT - HIT - 0.4) / cyc);
  if (label && reps >= 1) tl.fromTo(lab, { scale: 1 }, { scale: 1.1, duration: cyc / 2, ease: "sine.inOut", yoyo: true, repeat: reps * 2 - 1, immediateRender: false }, HIT + 0.35);
  // exit
  if (label) tl.to(badge, { scale: 0, rotation: 90, duration: 0.18, ease: "back.in(2)" }, OUT);
  tl.to(panels[0], { x: offL, duration: 0.3, ease: "power3.in" }, OUT + 0.06);
  tl.to(panels[1], { x: offR, duration: 0.3, ease: "power3.in" }, OUT + 0.06);
  return tl;
});

