#rk-shake { position: absolute; inset: 0; }
#rk-rays { position: absolute; left: 0; top: 0; overflow: visible; }
#rk-badge {
  position: absolute; --bc: var(--rk-c, var(--gold)); border-width: 4px;
  box-shadow: inset 7px 7px 0 rgba(255,255,255,0.35), inset -7px -7px 0 rgba(0,0,0,0.28), 8px 10px 0 0 #000;
