  box-shadow: inset 4px 4px 0 rgba(255,255,255,0.14), inset -4px -4px 0 rgba(0,0,0,0.4), 7px 8px 0 0 rgba(0,0,0,0.5); }
#rk-title { position: absolute; left: 0; width: 100%; text-align: center; line-height: 1.06; color: var(--paper); }
#rk-title .mc-line { white-space: nowrap; }

