input.content:
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, V = d.vertical;
  var INK = "#121315", PAPER = "#F4F1E8";
  var num = String(v.number == null ? "" : v.number).replace(/^#/, "").trim() || "1";
  var title = MC.plain(String(v.title || "")).toUpperCase().trim();
  var accent = String(v.accent || "#FFCC33");
  var f = function (n) { return n.toFixed(1); };

  // ---- layout
  var BS = V ? 190 : 176;                        // badge size
  var barH, barW, bx, by, barX, barY, fit;
  if (!V) {
    barW = Math.round(W * 0.5);
    fit = MC.fit(title || " ", { maxWidth: barW - BS * 0.32 - 40, maxSize: 46, minSize: 18, k: 0.5, maxLines: 2, lineHeight: 1.06, maxHeight: BS * 0.62 });
    barH = Math.round(Math.max(BS * 0.5, fit.lines.length * fit.size * 1.06 + fit.size * 0.9));
    var groupW = BS + barW - BS * 0.3;
    bx = Math.round((W - groupW) / 2); by = Math.round(H * 0.5 - BS / 2);
    barX = bx + BS * 0.7; barY = Math.round(by + BS / 2 - barH / 2);
  } else {
    barW = Math.round(W * 0.88);
    fit = MC.fit(title || " ", { maxWidth: barW - 44, maxSize: 50, minSize: 20, k: 0.5, maxLines: 3, lineHeight: 1.06, maxHeight: H * 0.16 });
    barH = Math.round(fit.lines.length * fit.size * 1.06 + fit.size * 1.6);
    bx = Math.round((W - BS) / 2); by = Math.round(H * 0.3);
    barX = Math.round((W - barW) / 2); barY = by + BS - 26;
  }
  var cx = bx + BS / 2, cy = by + BS / 2;

  // badge
  var badge = document.getElementById("rk-badge");
  badge.style.setProperty("--rk-c", accent);
  badge.style.left = bx + "px"; badge.style.top = by + "px";
  badge.style.width = BS + "px"; badge.style.height = BS + "px";
  var nEl = document.getElementById("rk-num"), nn = document.getElementById("rk-n");
  nn.textContent = num;
  var nSize = Math.floor(Math.min(BS * 0.66, (BS * 0.84) / ((num.length + 0.55) * 0.6)));
  nEl.style.fontSize = nSize + "px";
  nEl.style.top = (BS / 2 - nSize * 0.5 + nSize * 0.04) + "px";
  var fg = MC.onColor(accent, INK, PAPER);
  nEl.style.color = fg; nEl.style.setProperty("--ol", fg === INK ? PAPER : "#000");

  // title bar
  var bw = document.getElementById("rk-barwrap"), bar = document.getElementById("rk-bar"), tEl = document.getElementById("rk-title");
  bw.style.left = barX + "px"; bw.style.top = barY + "px";
  bar.style.width = barW + "px"; bar.style.height = barH + "px";
  tEl.style.fontSize = fit.size + "px";
  var parts = MC.renderLines(tEl, fit.lines);
  var th = fit.lines.length * fit.size * 1.06;
  if (!V) { tEl.style.left = (BS * 0.32) + "px"; tEl.style.width = (barW - BS * 0.32 - 8) + "px"; tEl.style.top = ((barH - 8 - th) / 2 + fit.size * 0.08) + "px"; }
  else tEl.style.top = ((barH - 8 - th) / 2 + 12 + fit.size * 0.08) + "px";
  if (!title) bw.style.display = "none";

  // rays
  var rays = document.getElementById("rk-rays");
  rays.setAttribute("width", W); rays.setAttribute("height", H); rays.setAttribute("viewBox", "0 0 " + W + " " + H);
  var RR = BS * (V ? 1.25 : 1.15), rs = "", NR = 14;
  for (var i = 0; i < NR; i++) {
    var a0 = (i / NR) * Math.PI * 2, a1 = a0 + Math.PI / NR * 0.9;
    rs += '<path d="M' + f(cx) + "," + f(cy) + " L" + f(cx + Math.cos(a0) * RR) + "," + f(cy + Math.sin(a0) * RR) + " L" + f(cx + Math.cos(a1) * RR) + "," + f(cy + Math.sin(a1) * RR) + ' Z" fill="' + accent + '" stroke="#000" stroke-width="3" stroke-linejoin="round"/>';
  }
  rays.innerHTML = '<g id="rk-rays-g" opacity="0.9">' + rs + '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(BS * 0.72) + '" fill="' + MC.shade(accent, -0.35) + '" stroke="#000" stroke-width="3"/></g>';
  var raysG = document.getElementById("rk-rays-g");

  // ---- timeline
  var tl = gsap.timeline({ paused: true });
  tl.fromTo(raysG, { scale: 0, rotation: -40, svgOrigin: cx + " " + cy }, { scale: 1, rotation: 0, duration: 0.42, ease: "back.out(1.8)" }, 0.08);
  tl.to(raysG, { rotation: 40, duration: d.duration - 0.5, ease: "none" }, 0.5);
  tl.fromTo(badge, { y: -(by + BS + 40), rotation: -35 }, { y: 0, rotation: -6, duration: 0.34, ease: "back.out(1.5)" }, 0);
  var HIT = 0.36;
  tl.fromTo(nEl, { scale: 3, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.14, ease: "power3.in" }, HIT - 0.14);
  tl.fromTo(nEl, { scaleX: 1, scaleY: 1 }, { keyframes: [{ scaleX: 1.2, scaleY: 0.82, duration: 0.05 }, { scaleX: 0.95, scaleY: 1.06, duration: 0.08 }, { scaleX: 1, scaleY: 1, duration: 0.12 }], ease: "power2.out", immediateRender: false }, HIT);
  var shake = document.getElementById("rk-shake"), A = 9;
  tl.fromTo(shake, { x: 0, y: 0 }, { keyframes: [{ x: A, y: -A * 0.5 }, { x: -A * 0.7, y: A * 0.5 }, { x: A * 0.35, y: A * 0.2 }, { x: 0, y: 0 }], duration: 0.22, ease: "none", immediateRender: false }, HIT);
  if (title) {
    tl.fromTo(bar, V ? { yPercent: -110 } : { xPercent: -105 }, V ? { yPercent: 0, duration: 0.3, ease: "power4.out" } : { xPercent: 0, duration: 0.3, ease: "power4.out" }, HIT + 0.1);
    tl.fromTo(parts.words, { scale: 0, y: 10 }, { scale: 1, y: 0, duration: 0.2, ease: "back.out(2.2)", stagger: Math.min(0.06, 0.4 / Math.max(parts.words.length, 1)) }, HIT + 0.24);
  }
  // hold: badge wobble (finite)
  var OUT = d.duration - 0.34, cyc = 0.8, reps = Math.floor((OUT - 1.0) / cyc);
  if (reps >= 1) tl.fromTo(badge, { rotation: -6 }, { rotation: 3, duration: cyc / 2, ease: "sine.inOut", yoyo: true, repeat: reps * 2 - 1, immediateRender: false }, 0.95);
  // exit
  if (title) tl.to(bar, V ? { yPercent: -110, duration: 0.2, ease: "power3.in" } : { xPercent: -105, duration: 0.2, ease: "power3.in" }, OUT);
  tl.to(badge, { scale: 0, rotation: 40, duration: 0.22, ease: "back.in(2)" }, OUT + 0.1);
  tl.to(raysG, { scale: 0, duration: 0.22, ease: "power2.in" }, OUT + 0.1);
  return tl;
});

